def recipe_fingerprint(config, weight_hashes):
    semantic = {k: deepcopy(config[k]) for k in ("pose", "skeleton", "quality", "features")}
    if not semantic["pose"].get("flip_tta", False):
        semantic["pose"].pop("flip_tta", None)
    if semantic["skeleton"].get("coordinate_normalization", "per_frame") == "per_frame":
        semantic["skeleton"].pop("coordinate_normalization", None)
    if semantic["skeleton"].get("temporal_context", "original_30") == "original_30":
        semantic["skeleton"].pop("temporal_context", None)
    if not semantic["pose"].get("use_track_proposals", False):
        semantic["pose"].pop("use_track_proposals", None)
    if semantic["skeleton"].get("timestamp_tolerance_ms", 0.0) == 0.0:
        semantic["skeleton"].pop("timestamp_tolerance_ms", None)
    if semantic["pose"].get("track_gap_tolerance_ms", 0.0) == 0.0:
        semantic["pose"].pop("track_gap_tolerance_ms", None)
    if semantic["pose"].get("fallback_detector_confidence", 0.0) == 0.0:
        semantic["pose"].pop("fallback_detector_confidence", None)
    if semantic["skeleton"].get("resampling_hold_policy") == "target_interval":
        semantic["skeleton"].pop("resampling_hold_policy")
    # Default [0] is the historical algorithm; preserve old frozen run fingerprints.
    if semantic["pose"].get("rotation_angles") == [0]:
        semantic["pose"].pop("rotation_angles")
        semantic["pose"].pop("rotation_policy", None)
    elif semantic["pose"].get("rotation_policy") == "always":
        semantic["pose"].pop("rotation_policy")
    temporal = {
        k: config["data"][k]
        for k in (
            "timestamp_policy",
            "fallback_fps",
            "camera",
            "modality",
            "allow_missing_timestamp_tail",
        )
    }
    return fingerprint(
        {
            "schema_version": 1,
            "preprocessing_version": 1,
            "upstream_commits": upstream_commits(config),
            "config": semantic,
            "temporal": temporal,
            "weight_hashes": weight_hashes,
        }
    )

def evaluate_one(run, output, audit):
    scorer = experiment.Scorer(run)
    rows, windows, events = [], [], []
    with scoped_access(scorer.index, audit):
        for source in scorer.index["split_manifest"]["sequences"]:
            if source["split"] != "validation":
                continue
            cache = experiment.cache_for(scorer.index, source["sequence_id"])
            summary, sw, se = score_sequence(
                cache, scorer.score(cache.features), scorer.threshold["threshold"]
            )
            rows.append({**summary, "label": source["label"]})
            windows.extend(sw)
            events.extend(se)
    if len(rows) != 23:
        raise ContractError("Every original Validation video required")
    metrics = {"source_kind": "real", **sequence_metrics(rows)}
    evaluation_report(output, metrics, rows, windows, events)
    return {
        "metrics": metrics,
        "rows": rows,
        "windows": windows,
        "events": events,
        "threshold": scorer.threshold["threshold"],
        "run": str(run.relative_to(ROOT)),
    }
